hl.monitor({
    output = "",
    mode = "preferred",
    position = "auto",
    scale = "auto",
})

hl.monitor({
    output = "HDMI-A-1",
    mode = "2560x1080@74.99Hz",
    position = "auto",
    scale = "auto",
})

-- This is an additional key binding
--$mainMod = SUPER
--$menu = rofi -show
local terminal = "kitty"

--exec-once = dbus-update-activation-environment --systemd HYPRLAND_INSTANCE_SIGNATURE  #hyprshade conf

-- Configuração para o ActivityWatch
-- Servidor principal limpa e inicia o log

-- Watcher unificado do Wayland (Janelas + AFK) adiciona seus logs

--exec = hyprshade auto
-- Verifica o horário ao iniciar. Se for entre 19h e 07h, liga o shader.

--bind = $mainMod, SPACE, exec, $menu
--bind = $mainMod, M, exit,
hl.bind("CTRL + Alt_l + T", hl.dsp.exec_cmd(terminal .. " bashtop"))
hl.bind("CTRL + Alt_l + 9", hl.dsp.exec_cmd("hyprshade auto && notify-send \"Exec HyprShade\""))

-- These binds will take a shot of the screen
hl.bind("print", hl.dsp.exec_cmd("hyprshot -m window"))
hl.bind("SHIFT + print", hl.dsp.exec_cmd("hyprshot -m region"))

-- Change the audio output
hl.bind("CTRL + Shift_l + 1", hl.dsp.exec_cmd("pactl set-default-sink alsa_output.pci-0000_30_00.1.hdmi-stereo && notify-send \"Saída de áudio: Monitor\""))
hl.bind("CTRL + Shift_l + 2", hl.dsp.exec_cmd("pactl set-default-sink alsa_output.usb-Sony_Interactive_Entertainment_Wireless_Headset-00.analog-stereo && notify-send \"Saída de áudio: Fone Wireless\""))

--Example for xwayland
