-- qt5ct environment variable
-- env = QT_QPA_PLATFORMTHEME,qt5ct

-- SDL version
hl.env("SDL_VIDEODRIVER", "wayland")
-- env = SDL_VIDEODRIVER,x11

-- No Hardware Cursor
-- cursor {
--     no_hardware_cursors = false
-- }

-- Blur for waybar
--layerrule = blur, waybar

hl.env("GTK_IM_MODULE", "fcitx")
hl.env("QT_IM_MODULE", "fcitx")
hl.env("XMODIFIERS", "@im=fcitx")
hl.config({
    general = {
        border_size = 1,
    },
    decoration = {
        active_opacity = 0.95,
        inactive_opacity = 0.85,
        blur = {
            enabled = true,
            xray = true,
            special = false,
            new_optimizations = true,
            size = 10,
            passes = 3,
            brightness = 1,
            noise = 0.05,
            contrast = 0.89,
            vibrancy = 0.5,
            vibrancy_darkness = 0.5,
            popups = false,
            popups_ignorealpha = 0.6,
            input_methods = true,
            input_methods_ignorealpha = 0.8,
        },
    },
    input = {
        kb_layout = "br",
        kb_variant = "",
        kb_model = "",
        kb_options = "",
        kb_rules = "",
        follow_mouse = 1,
        sensitivity = 0, -- -1.0 - 1.0, 0 means no modification.
        tablet = {
            left_handed = true,
        },
        touchpad = {
            natural_scroll = false,
        },
    },
    -- Fcitx5 + Mozc config
})

hl.on("hyprland.start", function()
    hl.exec_cmd(terminal)
    hl.exec_cmd("dbus-update-activation-environment --systemd HYPRLAND_INSTANCE_SIGNATURE")
    hl.exec_cmd("nmcli radio wifi on && nmcli connection up ZXL 1")
    hl.exec_cmd("/opt/activitywatch/aw-server/aw-server > ~/.aw-server.log 2>&1")
    hl.exec_cmd("aw-awatcher >> ~/.aw-server.log 2>&1")
    hl.exec_cmd("fcitx5 -d")
    hl.exec_cmd("hyprshade auto")
    --hl.exec_cmd("fish -c \"set hora (date +%H); if test \\$hora -ge 19 -o \\$hora -lt 07; hyprctl keyword decoration:screen_shader '~/.config/hypr/shaders/blue-light-filter.glsl'; end\"")
end)

hl.on("config.reloaded", function()
    hl.exec_cmd("hyprshade auto")
end)

